using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Xml.Linq;
namespace Citograph.Word {
 internal class FieldRecord {public dynamic field;public CitationPayload payload;public string error;public int position;public int story;public int noteIndex;}
 internal class DocumentController {
  public const string Namespace="https://citograph.local/word/v1";public const string BibliographyTag="Citograph.Bibliography";
  private dynamic application;private BridgeClient bridge;private object scopedDocument;
  public DocumentController(dynamic app,BridgeClient client,object target=null){application=app;bridge=client;scopedDocument=target;}
  public dynamic Document {get{if(application==null||(int)application.Documents.Count==0)throw new InvalidOperationException("Open a Word document first.");dynamic doc=scopedDocument??(object)application.ActiveDocument;if(doc.ReadOnly)throw new InvalidOperationException("This document is read-only. Open an editable copy first.");return doc;}}
  public DocumentLibrary Library(){dynamic doc=Document;dynamic parts=doc.CustomXMLParts.SelectByNamespace(Namespace);if((int)parts.Count==0)return new DocumentLibrary();try{var xml=XElement.Parse((string)parts.Item(1).XML);var text=xml.Descendants(XName.Get("payload",Namespace)).First().Value;var data=Data.Parse<DocumentLibrary>(Encoding.UTF8.GetString(Convert.FromBase64String(text)));if(data.schemaVersion!=1||data.references==null)throw new InvalidDataException();return data;}catch(Exception e){throw new InvalidDataException("The document's Citograph library is damaged. Export a copy of the document before repairing it.",e);}}
  internal void SaveLibrary(DocumentLibrary data){dynamic doc=Document;dynamic previous=doc.CustomXMLParts.SelectByNamespace(Namespace);var old=new List<object>();for(int i=1;i<=(int)previous.Count;i++)old.Add(previous.Item(i));var xml=new XElement(XName.Get("citograph",Namespace),new XAttribute("version","1"),new XElement(XName.Get("payload",Namespace),new XAttribute("encoding","base64"),Convert.ToBase64String(Encoding.UTF8.GetBytes(Data.Serialize(data)))));doc.CustomXMLParts.Add(xml.ToString(SaveOptions.DisableFormatting));foreach(dynamic part in old)part.Delete();}
  internal static string Code(CitationPayload payload){return " ADDIN CITOGRAPH/1 "+Convert.ToBase64String(Encoding.UTF8.GetBytes(Data.Serialize(payload)))+" ";}
  private static CitationPayload Decode(dynamic field){string code=(string)field.Code.Text;var match=Regex.Match(code,@"\bCITOGRAPH/1\s+([A-Za-z0-9+/=]+)");if(!match.Success)throw new InvalidDataException("Citation data is missing.");var payload=Data.Parse<CitationPayload>(Encoding.UTF8.GetString(Convert.FromBase64String(match.Groups[1].Value)));if(payload.schemaVersion!=1||string.IsNullOrEmpty(payload.id)||payload.items==null||payload.references==null||payload.items.Count==0)throw new InvalidDataException("Citation data is incompatible.");return payload;}
  private static bool IsCitograph(dynamic field){try{return (int)field.Type==81&&Regex.IsMatch((string)field.Code.Text,@"^\s*ADDIN\s+CITOGRAPH/1(\s|$)");}catch{return false;}}
  public List<FieldRecord> Fields(){dynamic doc=Document;var fields=new List<FieldRecord>();foreach(dynamic initial in doc.StoryRanges){dynamic range=initial;while(range!=null){int story=(int)range.StoryType;if(story==1||story==2||story==3){foreach(dynamic field in range.Fields){if(!IsCitograph(field))continue;var record=new FieldRecord{field=field,story=story,position=(int)field.Result.Start};if(story!=1){dynamic notes=story==2?doc.Footnotes:doc.Endnotes;foreach(dynamic note in notes){if((int)field.Result.Start>=(int)note.Range.Start&&(int)field.Result.End<=(int)note.Range.End){record.position=(int)note.Reference.Start;record.noteIndex=(int)note.Index;break;}}}try{record.payload=Decode(field);}catch(Exception e){record.error=e.Message;}fields.Add(record);}}try{range=range.NextStoryRange;}catch{range=null;}}}return fields.OrderBy(f=>f.position).ThenBy(f=>f.story).ToList();}
  private DocumentLibrary Reconcile(DocumentLibrary data,List<FieldRecord> fields){var refs=new List<Dictionary<string,object>>(data.references);var ids=new HashSet<string>();foreach(var f in fields){if(f.payload==null)throw new InvalidDataException("A damaged citation was found. Use Document check to locate it.");if(!ids.Add(f.payload.id)){f.payload.id=Guid.NewGuid().ToString();ids.Add(f.payload.id);}refs.AddRange(f.payload.references);}data.references=Data.Unique(refs);return data;}
  public List<Dictionary<string,object>> TravelingReferences(){var fields=Fields();var data=Reconcile(Library(),fields);var cited=new HashSet<string>(fields.SelectMany(f=>f.payload.items.Select(i=>i.id)));return data.references.Where(r=>cited.Contains(Data.Text(r,"id"))).ToList();}
  public string Insert(List<Dictionary<string,object>> refs,string locator,string prefix,string suffix,bool suppress){if(refs.Count==0)throw new InvalidOperationException("Select at least one source.");dynamic doc=Document;dynamic range=application.Selection.Range.Duplicate;range.Collapse(0);foreach(var existing in Fields())if((int)range.StoryType==existing.story&&(int)range.Start>=(int)existing.field.Result.Start&&(int)range.Start<=(int)existing.field.Result.End)throw new InvalidOperationException("Move the cursor outside the citation, or use Edit citation.");var data=Library();data.references=Data.Unique(data.references.Concat(refs));var payload=new CitationPayload{references=refs};payload.items=refs.Select((r,i)=>new CitationItem{id=Data.Text(r,"id"),locator=locator,prefix=i==0?prefix:null,suffix=i==refs.Count-1?suffix:null,suppressAuthor=suppress}).ToList();range.InsertXML(RichText.CitationField(Code(payload)));dynamic field=Fields().First(f=>f.payload!=null&&f.payload.id==payload.id).field;SaveLibrary(data);try{Update();}catch{field.Result.Text="[Citograph: update required]";throw;}dynamic after=field.Result.Duplicate;after.SetRange((int)field.Result.End+1,(int)field.Result.End+1);after.Select();return payload.id;}
  public string InsertByIds(string ids,string locator,string prefix,string suffix,bool suppress){var library=bridge.Library();var selected=new HashSet<string>(ids.Split(',').Where(i=>i.Length>0));var refs=library.references.Where(r=>selected.Contains(Data.Text(r,"id"))).ToList();if(refs.Count!=selected.Count)throw new InvalidOperationException("One or more selected sources are unavailable in Citograph.");return Insert(refs,locator,prefix,suffix,suppress);}
  public FieldRecord SelectedCitation(){dynamic selected=application.Selection.Range;foreach(var f in Fields())if(f.story==(int)selected.StoryType&&(int)selected.Start>=(int)f.field.Code.Start-1&&(int)selected.Start<=(int)f.field.Result.End+1)return f;throw new InvalidOperationException("Place the cursor in a Citograph citation first.");}
  public void Edit(FieldRecord field,List<Dictionary<string,object>> refs,string locator,string prefix,string suffix,bool suppress){if(refs.Count==0)throw new InvalidOperationException("A citation must contain at least one source.");var payload=field.payload;payload.references=refs;payload.items=refs.Select((r,i)=>new CitationItem{id=Data.Text(r,"id"),locator=locator,prefix=i==0?prefix:null,suffix=i==refs.Count-1?suffix:null,suppressAuthor=suppress}).ToList();field.field.Locked=false;field.field.Code.Text=Code(payload);var data=Library();data.references=Data.Unique(data.references.Concat(refs));SaveLibrary(data);Update();}
  public void SetStyle(string id){UpdateWithStyle(id);}
  private static void ApplyInline(dynamic range,string html){var segments=RichText.Inline(html);range.Text=string.Concat(segments.Select(s=>s.text));int start=(int)range.Start;range.Font.Bold=0;range.Font.Italic=0;range.Font.Superscript=0;range.Font.Subscript=0;int offset=0;foreach(var s in segments){if(s.text.Length==0)continue;dynamic part=range.Duplicate;part.SetRange(start+offset,start+offset+s.text.Length);if(s.bold)part.Font.Bold=-1;if(s.italic)part.Font.Italic=-1;if(s.vertical=="superscript")part.Font.Superscript=-1;if(s.vertical=="subscript")part.Font.Subscript=-1;offset+=s.text.Length;}}
  public string Update(){return UpdateWithStyle(null);} private string UpdateWithStyle(string styleOverride){dynamic doc=Document;var fields=Fields();var data=Reconcile(Library(),fields);if(styleOverride!=null){data.style=styleOverride;data.styleXml=null;data.localeXml=null;}var cited=new HashSet<string>(fields.SelectMany(f=>f.payload.items.Select(i=>i.id)));var refs=data.references.Where(r=>cited.Contains(Data.Text(r,"id"))).ToList();var request=new FormatRequest{references=refs,clusters=fields.Select(f=>new FormatCluster{id=f.payload.id,items=f.payload.items,noteIndex=f.story==1?0:Math.Max(1,f.noteIndex)}).ToList(),style=data.style,styleXml=data.styleXml,localeXml=data.localeXml};var formatted=bridge.Format(request);bool previous=application.ScreenUpdating;application.ScreenUpdating=false;bool undo=false;try{try{application.UndoRecord.StartCustomRecord("Citograph: update citations and bibliography");undo=true;}catch{}foreach(var f in fields.OrderByDescending(f=>f.position)){string html;if(!formatted.citations.TryGetValue(f.payload.id,out html))throw new InvalidDataException("Formatting returned an incomplete citation set.");f.payload.references=refs.Where(r=>f.payload.items.Any(i=>i.id==Data.Text(r,"id"))).ToList();f.field.Locked=false;f.field.Code.Text=Code(f.payload);f.field.Locked=true;ApplyInline(f.field.Result,html);f.field.Locked=true;}data.styleXml=formatted.styleXml;data.localeXml=formatted.localeXml;dynamic controls=doc.SelectContentControlsByTag(BibliographyTag);for(int i=1;i<=(int)controls.Count;i++)ApplyBibliography(controls.Item(i),formatted.bibliography,data.bibliographyTitle);SaveLibrary(data);}finally{if(undo)application.UndoRecord.EndCustomRecord();application.ScreenUpdating=previous;}return Data.Serialize(new {citations=fields.Count,sources=refs.Count,style=data.style,bibliographies=(int)doc.SelectContentControlsByTag(BibliographyTag).Count});}
  private void ApplyBibliography(dynamic control,string html,string title){control.LockContents=false;try{control.Range.InsertXML(RichText.Ooxml(html,true,title));}finally{control.LockContents=true;control.LockContentControl=false;}}
  public string Bibliography(){dynamic doc=Document;dynamic controls=doc.SelectContentControlsByTag(BibliographyTag);if((int)controls.Count==0){dynamic range=doc.Content.Duplicate;range.Collapse(0);range.MoveStart(1,-1);range.Collapse(1);range.InsertBefore("\r");range.Collapse(0);dynamic control=doc.ContentControls.Add(0,range);control.Tag=BibliographyTag;control.Title="Citograph bibliography";control.Range.Text="References\r[Update citations to generate your bibliography]";}return Update();}
  public string RefreshMetadata(){var live=bridge.Library();var data=Reconcile(Library(),Fields());int refreshed=0;for(int i=0;i<data.references.Count;i++){var source=data.references[i];var current=live.references.FirstOrDefault(r=>Data.Text(r,"id")==Data.Text(source,"id")||(!string.IsNullOrEmpty(Data.Text(source,"DOI"))&&Data.Text(r,"DOI").Equals(Data.Text(source,"DOI"),StringComparison.OrdinalIgnoreCase)));if(current!=null){var copy=new Dictionary<string,object>(current);copy["id"]=Data.Text(source,"id");data.references[i]=copy;refreshed++;}}SaveLibrary(data);Update();return Data.Serialize(new {refreshed});}
  public string Audit(){var fields=Fields();var issues=new List<string>();var valid=fields.Where(f=>f.payload!=null).ToList();foreach(var f in fields.Where(f=>f.payload==null))issues.Add("Damaged citation at position "+f.position+": "+f.error);var refs=Data.Unique(Library().references.Concat(valid.SelectMany(f=>f.payload.references)));foreach(var f in valid)foreach(var item in f.payload.items)if(!Data.HasId(refs,item.id))issues.Add("Missing source "+item.id+" in citation at position "+f.position);foreach(var r in refs){var missing=new List<string>();if(string.IsNullOrEmpty(Data.Text(r,"title")))missing.Add("title");if(Data.Authors(r)=="Unknown author")missing.Add("author");if(string.IsNullOrEmpty(Data.Year(r)))missing.Add("year");if(missing.Count>0)issues.Add(Data.Text(r,"title")+": missing "+string.Join(", ",missing));}int duplicates=valid.GroupBy(f=>f.payload.id).Count(g=>g.Count()>1);if(duplicates>0)issues.Add(duplicates+" pasted citation IDs will be repaired by Update citations.");return Data.Serialize(new {citations=fields.Count,sources=refs.Count,bibliographies=(int)Document.SelectContentControlsByTag(BibliographyTag).Count,style=Library().style,issues});}
  public string ExportTraveling(){return Data.Serialize(new {schemaVersion=1,source="Citograph Word traveling library",style=Library().style,references=TravelingReferences()});}
  public string ImportToDesktop(){var result=bridge.Import(TravelingReferences());return Data.Serialize(result);}
  public string BibliographyMarkup(){var fields=Fields();var data=Reconcile(Library(),fields);var cited=new HashSet<string>(fields.SelectMany(f=>f.payload.items.Select(i=>i.id)));var request=new FormatRequest{references=data.references.Where(r=>cited.Contains(Data.Text(r,"id"))).ToList(),clusters=fields.Select(f=>new FormatCluster{id=f.payload.id,items=f.payload.items,noteIndex=f.story==1?0:Math.Max(1,f.noteIndex)}).ToList(),style=data.style,styleXml=data.styleXml,localeXml=data.localeXml};return bridge.Format(request).bibliography;}
  public void ConvertToText(){dynamic doc=Document;foreach(var f in Fields().OrderByDescending(f=>f.position)){f.field.Locked=false;f.field.Unlink();}dynamic controls=doc.SelectContentControlsByTag(BibliographyTag);for(int i=(int)controls.Count;i>=1;i--){dynamic c=controls.Item(i);c.LockContents=false;c.LockContentControl=false;c.Delete(false);}dynamic parts=doc.CustomXMLParts.SelectByNamespace(Namespace);for(int i=(int)parts.Count;i>=1;i--)parts.Item(i).Delete();}
 }
}
